/**
 * Secrets SampCode makes for itself (ADR 0043). JWT_SECRET (sign-in sessions) and SIGNING_KEYS_SECRET
 * (test links, duplicate-check hashes, SSO state) no longer have to be generated by whoever installs
 * SampCode: on the first start the API (or the worker, whichever starts first) creates both, seals them
 * with SECRETS_KEY and stores them in MongoDB; every later start, and every other process, reads them
 * back. An environment variable of the same name still wins, so a server that already has them keeps
 * its sessions and links.
 *
 * SECRETS_KEY, the master key that seals all of these (and every API key saved in Settings >
 * Integrations), is not kept in the database it protects. It comes from the environment, or from the
 * file named by SECRETS_KEY_FILE: docker-compose.prod.yml writes a random one into its own volume on the
 * first start, so nobody has to make it (keep a copy off the server: see docs/operations/go-live.md).
 *
 * Runs before anything reads the configuration (config() needs JWT_SECRET), so it reads process.env
 * itself and puts the values there.
 */
import { randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { PrismaClient } from '@zapx/db';
import { LocalSecretBox } from './secret-box';

export const GENERATED_SECRETS = ['JWT_SECRET', 'SIGNING_KEYS_SECRET'] as const;
type Name = (typeof GENERATED_SECRETS)[number];
const ROW_ID = 'installation';

type Db = Pick<PrismaClient, 'installationSecret'>;

/**
 * Fills in JWT_SECRET and SIGNING_KEYS_SECRET from the database (creating them on the first start)
 * when the environment does not set them. Returns the names it filled in.
 */
export async function loadInstallationSecrets(env: NodeJS.ProcessEnv = process.env, db?: Db): Promise<Name[]> {
  if (!env.SECRETS_KEY && env.SECRETS_KEY_FILE) {
    try {
      env.SECRETS_KEY = readFileSync(env.SECRETS_KEY_FILE, 'utf8').trim();
    } catch (e) {
      throw new Error(`SECRETS_KEY_FILE (${env.SECRETS_KEY_FILE}) cannot be read: ${(e as Error).message}`);
    }
  }
  const needed = GENERATED_SECRETS.filter((n) => !env[n]);
  if (!needed.length) return [];
  if (!env.SECRETS_KEY)
    throw new Error(
      `SECRETS_KEY is not set. SampCode needs it to keep ${needed.join(' and ')} (which it makes itself) and every saved API key ` +
        'encrypted in the database. Generate one with `openssl rand -hex 32` and set SECRETS_KEY (or SECRETS_KEY_FILE).',
    );
  const box = new LocalSecretBox(env.SECRETS_KEY);
  const own = !db;
  const prisma = db ?? new PrismaClient();
  try {
    let row = await prisma.installationSecret.findUnique({ where: { id: ROW_ID } });
    if (!row) {
      const fresh = Object.fromEntries(GENERATED_SECRETS.map((n) => [n, randomBytes(32).toString('hex')]));
      try {
        row = await prisma.installationSecret.create({ data: { id: ROW_ID, sealed: box.seal(JSON.stringify(fresh)) } });
      } catch {
        // Another process (the worker, a second API) created it at the same moment: use theirs.
        row = await prisma.installationSecret.findUnique({ where: { id: ROW_ID } });
        if (!row) throw new Error('Could not create or read the installation secrets in the database');
      }
    }
    let values: Partial<Record<Name, string>>;
    try {
      values = JSON.parse(box.open(row.sealed)) as Partial<Record<Name, string>>;
    } catch {
      throw new Error(
        'The secrets SampCode keeps in the database cannot be opened with this SECRETS_KEY. Put back the SECRETS_KEY this ' +
          'installation was started with (it is also needed for every API key saved in Settings > Integrations).',
      );
    }
    for (const n of needed) {
      const v = values[n];
      if (!v) throw new Error(`The installation secrets in the database have no ${n}`);
      env[n] = v;
    }
    return needed;
  } finally {
    if (own) await (prisma as PrismaClient).$disconnect();
  }
}

/**
 * Environment variables that used to hold third-party API keys. SampCode no longer reads them: the
 * keys are entered in Settings > Integrations (or the super admin console) and kept in MongoDB.
 */
export const RETIRED_ENV = [
  'ANTHROPIC_API_KEY',
  'AI_MODEL',
  'AI_MODEL_ARCHITECT',
  'AI_MODEL_TRANSLATE',
  'AI_MODEL_INSIGHTS',
  'AI_PRICING',
  'NETWORK_REPUTATION',
  'IPINFO_TOKEN',
  'TRANSCRIPTION',
  'DEEPGRAM_API_KEY',
  'DEEPGRAM_MODEL',
  'TELEPHONY',
  'TWILIO_ACCOUNT_SID',
  'TWILIO_AUTH_TOKEN',
  'TWILIO_CALLER_ID',
  'TELEPHONY_WEBHOOK_BASE',
  'SMS_PROVIDER',
  'SMS_FROM',
  'EMAIL_PROVIDER',
  'SENDGRID_API_KEY',
  'EMAIL_FROM',
  'EMAIL_FROM_NAME',
  'BILLING',
  'STRIPE_SECRET_KEY',
  'STRIPE_WEBHOOK_SECRET',
  'STRIPE_PRICES',
  'STRIPE_API_VERSION',
  'BILLING_FALLBACK_PLAN',
  'FILE_STORE',
  'S3_BUCKET',
  'S3_REGION',
  'S3_PREFIX',
  'S3_KMS_KEY_ID',
  'SAMPLEON_URL',
  'SAMPLEON_CLIENT_ID',
  'SAMPLEON_CLIENT_SECRET',
  'SAMPLEON_OUTCOME_SECRET',
] as const;

/** The retired variables that are still set, so the server can say they are ignored. */
export const retiredEnvInUse = (env: NodeJS.ProcessEnv = process.env) => RETIRED_ENV.filter((n) => !!env[n]);
